declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';security_headers();student_private_headers();$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Fferramentas.php',true,303);exit;}
$tools=student_tools_for_student($db,(int)$student['id']);$urls=['reciprocity'=>'/aluno/reciprocidade.php','exposure'=>'/aluno/exposicao.php','lab_timer'=>'/aluno/temporizador.php','calibration'=>'/aluno/calibracao.php','solution_prep'=>'/aluno/preparo-solucoes.php','lab_inventory'=>'/aluno/inventario.php'];$byKey=[];foreach($tools as $tool)$byKey[(string)$tool['tool_key']]=$tool;$groups=['Exposição'=>['exposure','reciprocity'],'Processamento'=>['lab_timer','calibration'],'Química e estoque'=>['solution_prep','lab_inventory']];student_shell_start('Laboratório',null,$student);?>
<p class="student-kicker">Fazer</p><h1 class="student-title">Laboratório</h1><p class="student-lead">Instrumentos de trabalho para usar durante a exposição, o processamento e o preparo químico.</p>
<?php if(!$tools):?><div class="student-empty">Nenhum instrumento está disponível para esta conta.</div><?php else:?><div class="student-lab-groups"><?php foreach($groups as $groupLabel=>$keys):$available=array_values(array_filter($keys,fn($key)=>isset($byKey[$key],$urls[$key])));if(!$available)continue;?><section class="student-lab-group"><div class="student-section-heading"><div><p class="student-kicker">Laboratório</p><h2 class="student-subtitle"><?=h($groupLabel)?></h2></div></div><div class="student-lab-list"><?php foreach($available as $key):$tool=$byKey[$key];?><article class="student-lab-row"><div><h3><?=h((string)$tool['label'])?></h3><p><?=h((string)$tool['description'])?></p></div><a class="button button-secondary" href="<?=h($urls[$key])?>">Abrir</a></article><?php endforeach;?></div></section><?php endforeach;?>
<section class="student-lab-group"><div class="student-section-heading"><div><p class="student-kicker">Reutilizar</p><h2 class="student-subtitle">Preparos salvos</h2></div></div><div class="student-lab-list"><article class="student-lab-row"><div><h3>Preparos pessoais</h3><p>Configurações de reveladores e preparações que você usa com frequência nos registros do Caderno.</p></div><a class="button button-secondary" href="/aluno/preparos.php">Abrir</a></article></div></section></div><?php endif;?>
<?php student_shell_end();
